/** XMLs de NF-e 4.00 no formato real da SEFAZ (dados fictícios): nfeProc, namespace, prefixo, aspas, quebras, modelo. */
export function real(opts: { ns?: boolean; proc?: boolean; aspas?: '"' | "'"; mod?: string; prefixo?: string; quebra?: boolean; chave?: string; cnpj?: string } = {}) {
  const q = opts.aspas ?? '"'; const p = opts.prefixo ? opts.prefixo + ':' : '';
  const ns = opts.ns === false ? '' : ` xmlns${opts.prefixo ? ':' + opts.prefixo : ''}=${q}http://www.portalfiscal.inf.br/nfe${q}`;
  const chave = opts.chave ?? '35251112345678000195550010000456781123456789';
  const nl = opts.quebra ? '\r\n  ' : '';
  const t = (n: string, v: string) => `<${p}${n}>${v}</${p}${n}>`;
  const det = (i: number, cProd: string, ean: string, xProd: string, cfop: string, u: string, qtd: string, vun: string, vprod: string) =>
    `<${p}det nItem=${q}${i}${q}>${nl}<${p}prod>${t('cProd', cProd)}${t('cEAN', ean)}${t('xProd', xProd)}${t('NCM', '39269090')}${t('CEST','2804100')}${t('CFOP', cfop)}${t('uCom', u)}${t('qCom', qtd)}${t('vUnCom', vun)}${t('vProd', vprod)}${t('cEANTrib', ean)}${t('uTrib', u)}${t('qTrib', qtd)}${t('vUnTrib', vun)}${t('indTot', '1')}</${p}prod>${nl}<${p}imposto>${t('vTotTrib','1.00')}<${p}ICMS><${p}ICMSSN102>${t('orig','0')}${t('CSOSN','102')}</${p}ICMSSN102></${p}ICMS><${p}IPI>${t('cEnq','999')}<${p}IPINT>${t('CST','53')}</${p}IPINT></${p}IPI><${p}PIS><${p}PISOutr>${t('CST','99')}${t('vBC','0.00')}${t('pPIS','0.0000')}${t('vPIS','0.00')}</${p}PISOutr></${p}PIS><${p}COFINS><${p}COFINSOutr>${t('CST','99')}${t('vBC','0.00')}${t('pCOFINS','0.0000')}${t('vCOFINS','0.00')}</${p}COFINSOutr></${p}COFINS></${p}imposto>${t('infAdProd','Item ' + i)}</${p}det>`;
  const nfe = `<${p}NFe${opts.proc ? '' : ns}><${p}infNFe versao=${q}4.00${q} Id=${q}NFe${chave}${q}>${nl}<${p}ide>${t('cUF','35')}${t('cNF','12345678')}${t('natOp','VENDA DE MERCADORIA')}${t('mod', opts.mod ?? '55')}${t('serie','1')}${t('nNF','45678')}${t('dhEmi','2025-11-20T10:15:00-03:00')}${t('dhSaiEnt','2025-11-20T10:15:00-03:00')}${t('tpNF','1')}${t('idDest','1')}${t('cMunFG','3550308')}${t('tpImp','1')}${t('tpEmis','1')}${t('cDV','9')}${t('tpAmb','1')}${t('finNFe','1')}${t('indFinal','0')}${t('indPres','1')}${t('procEmi','0')}${t('verProc','UniNFe 5.0')}</${p}ide>${nl}<${p}emit>${t('CNPJ', opts.cnpj ?? '12345678000195')}${t('xNome','DISTRIBUIDORA EXEMPLO DE PAPELARIA LTDA')}${t('xFant','DIST EXEMPLO')}<${p}enderEmit>${t('xLgr','RUA DAS FLORES')}${t('nro','100')}${t('xBairro','CENTRO')}${t('cMun','3550308')}${t('xMun','SAO PAULO')}${t('UF','SP')}${t('CEP','01001000')}${t('cPais','1058')}${t('xPais','BRASIL')}${t('fone','1133334444')}</${p}enderEmit>${t('IE','111222333444')}${t('CRT','1')}</${p}emit>${nl}<${p}dest>${t('CNPJ','11222333000181')}${t('xNome','LOJA EXEMPLO LTDA')}<${p}enderDest>${t('xLgr','RUA X')}${t('nro','1')}${t('xBairro','B')}${t('cMun','3509502')}${t('xMun','CAMPINAS')}${t('UF','SP')}${t('CEP','13000000')}</${p}enderDest>${t('indIEDest','9')}${t('email','compras@example.com')}</${p}dest>${nl}` +
    det(1, '7891', '7891234567895', 'CANETA ESFEROGRAFICA AZUL CX 50', '5102', 'CX', '2.0000', '45.5000000000', '91.00') +
    det(2, 'A4-500', 'SEM GTIN', 'PAPEL SULFITE A4 75G PCT 500 FLS', '5405', 'PCT', '10.0000', '24.9000', '249.00') +
    det(3, 'GRAMP', '', 'GRAMPEADOR METAL 26/6 - AÇÃO RÁPIDA', '6102', 'UN', '1.5000', '30.00', '45.00') +
    `<${p}total><${p}ICMSTot>${t('vBC','0.00')}${t('vICMS','0.00')}${t('vProd','385.00')}${t('vFrete','0.00')}${t('vNF','385.00')}</${p}ICMSTot></${p}total><${p}transp>${t('modFrete','9')}</${p}transp><${p}cobr><${p}fat>${t('nFat','45678')}${t('vOrig','385.00')}${t('vLiq','385.00')}</${p}fat><${p}dup>${t('nDup','001')}${t('dVenc','2025-12-20')}${t('vDup','385.00')}</${p}dup></${p}cobr><${p}pag><${p}detPag>${t('tPag','15')}${t('vPag','385.00')}</${p}detPag></${p}pag><${p}infAdic>${t('infCpl','DOCUMENTO EMITIDO POR ME OU EPP OPTANTE PELO SIMPLES NACIONAL')}</${p}infAdic><${p}infRespTec>${t('CNPJ','99999999000191')}${t('xContato','Suporte')}</${p}infRespTec></${p}infNFe><Signature xmlns="http://www.w3.org/2000/09/xmldsig#"><SignedInfo><CanonicalizationMethod Algorithm="http://www.w3.org/TR/2001/REC-xml-c14n-20010315"/><Reference URI="#NFe${chave}"><DigestValue>abc=</DigestValue></Reference></SignedInfo><SignatureValue>xyz</SignatureValue></Signature></${p}NFe>`;
  const prot = `<${p}protNFe versao=${q}4.00${q}><${p}infProt Id=${q}ID135250000000001${q}>${t('tpAmb','1')}${t('verAplic','SP_NFE_PL009_V4')}${t('chNFe',chave)}${t('dhRecbto','2025-11-20T10:16:00-03:00')}${t('nProt','135250000000001')}${t('digVal','abc=')}${t('cStat','100')}${t('xMotivo','Autorizado o uso da NF-e')}</${p}infProt></${p}protNFe>`;
  const corpo = opts.proc ? `<${p}nfeProc${ns} versao=${q}4.00${q}>${nfe}${prot}</${p}nfeProc>` : nfe;
  return `<?xml version="1.0" encoding="UTF-8"?>${nl}${corpo}`;
}
